# SPDX-License-Identifier: MIT
# What the oscilloscope measures with: an ADC input sampled at a fixed rate by the board (on the
# STM32MP157C-DK2 the Cortex-M4's TIM2 triggers each conversion), and a PWM test signal on D6.
# In the LVGL MPY Studio simulator a stand-in makes up signals: the test signal on A0, a 50 Hz
# sine on A1, noise elsewhere.

import math
import time

try:
    import machine

    HARDWARE = hasattr(machine, "ADC") and hasattr(machine.ADC, "capture")
except ImportError:
    machine = None
    HARDWARE = False

FULL_SCALE_MV = 2500  # the ADC's reference: 0 to 2.5 V on 16 bits


class Board:
    def __init__(self):
        self._adcs = {}
        self._adc = None
        self._pwm = None

    def start(self, pin, count, rate):
        # Start a capture of count samples at rate Hz; returns the exact rate.
        if pin not in self._adcs:
            self._adcs[pin] = machine.ADC(pin)
        self._adc = self._adcs[pin]
        return self._adc.capture(count, rate)

    def done(self):
        return self._adc.capture_done()

    def read(self, buf):
        self._adc.capture_read(buf)
        return self._adc.overruns

    def generator(self, on):
        if on and self._pwm is None:
            self._pwm = machine.PWM("D6", freq=1000, duty_u16=16384)  # 1 kHz, 25%
        elif not on and self._pwm is not None:
            self._pwm.deinit()
            self._pwm = None


class Simulated:
    def __init__(self):
        self._pin = "A0"
        self._rate = 1000
        self._count = 0
        self._start = 0
        self._generator = False

    def start(self, pin, count, rate):
        self._pin, self._count, self._rate = pin, count, rate
        self._start = time.ticks_ms()
        return float(rate)

    def done(self):
        return time.ticks_diff(time.ticks_ms(), self._start) >= self._count * 1000 // self._rate

    def _volts(self, t):
        if self._pin == "A0" and self._generator:
            return 2.5 if (t * 1000) % 1 < 0.25 else 0.0
        if self._pin == "A1":
            return 1.25 + 0.75 * math.sin(2 * math.pi * 50 * t)
        return 0.05 + 0.05 * math.sin(2 * math.pi * 3 * t)

    def read(self, buf):
        offset = self._start / 1000
        seed = self._start
        for i in range(min(len(buf), self._count)):
            seed = (seed * 1103515245 + 12345) & 0x7FFFFFFF
            noise = (seed % 200 - 100) / 10000
            volts = min(2.5, max(0.0, self._volts(offset + i / self._rate) + noise))
            buf[i] = int(volts * 65535 / 2.5)
        return 0

    def generator(self, on):
        self._generator = on


probe = Board() if HARDWARE else Simulated()
